Classic reverse union-find approach: remove all hits first, build DSU with a virtual roof node, then add bricks back in reverse order and measure the growth of the roof component.

```javascript
/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length, n = grid[0].length;
    const g = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        if (g[r][c] === 1) g[r][c] = 2; // mark removed brick
    }
    const N = m * n;
    const roof = N;
    const parent = new Int32Array(N + 1);
    const size = new Int32Array(N + 1);
    for (let i = 0; i <= N; i++) { parent[i] = i; size[i] = 1; }
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a, b) => {
        a = find(a); b = find(b);
        if (a === b) return;
        if (size[a] < size[b]) { const t = a; a = b; b = t; }
        parent[b] = a;
        size[a] += size[b];
    };
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] !== 1) continue;
            const id = r * n + c;
            if (r === 0) union(id, roof);
            if (r > 0 && g[r-1][c] === 1) union(id, (r-1) * n + c);
            if (c > 0 && g[r][c-1] === 1) union(id, r * n + c - 1);
        }
    }
    const res = new Array(hits.length).fill(0);
    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        if (g[r][c] !== 2) continue;
        const before = size[find(roof)];
        g[r][c] = 1;
        const id = r * n + c;
        if (r === 0) union(id, roof);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (g[nr][nc] === 1) union(id, nr * n + nc);
        }
        const after = size[find(roof)];
        res[i] = Math.max(0, after - before - 1);
    }
    return res;
};
```

