/**
 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const gcd = (a, b) => { while (b) { [a, b] = [b, a % b]; } return a; };
    const g = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) for (let j = i + 1; j < m; j++) g[i][j] = gcd(nums[i], nums[j]);
    const full = (1 << m) - 1;
    const dp = new Int32Array(1 << m).fill(-1);
    dp[0] = 0;
    const popcount = (x) => { let c = 0; while (x) { x &= x - 1; c++; } return c; };
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] < 0) continue;
        const cnt = popcount(mask);
        if (cnt & 1) continue;
        const op = cnt / 2 + 1;
        // pick first unused index to reduce symmetry
        let i = 0;
        while (mask & (1 << i)) i++;
        for (let j = i + 1; j < m; j++) {
            if (mask & (1 << j)) continue;
            const nm = mask | (1 << i) | (1 << j);
            const val = dp[mask] + op * g[i][j];
            if (val > dp[nm]) dp[nm] = val;
        }
    }
    return dp[full];
};
