Standard approach: track count of each number and frequency of each count. For prefix of length i+1 with max frequency maxF, valid if:
- maxF == 1 (remove any element), or
- freq[maxF] * maxF == i (all numbers have maxF except one with count 1), or
- freq[maxF-1] * (maxF-1) + maxF == i+1 (one number has maxF, rest have maxF-1).

```javascript
/**
 * @param {number[]} nums
 * @return {number}
 */
var maxEqualFreq = function(nums) {
    const count = new Int32Array(100002);
    const freq = new Int32Array(100002);
    let maxF = 0;
    let res = 0;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        if (count[x] > 0) freq[count[x]]--;
        count[x]++;
        freq[count[x]]++;
        if (count[x] > maxF) maxF = count[x];
        const len = i + 1;
        if (maxF === 1 ||
            freq[maxF] * maxF === len - 1 ||
            freq[maxF - 1] * (maxF - 1) + maxF === len) {
            res = len;
        }
    }
    return res;
};
