/**
 * @param {number} n
 * @param {number[]} batteries
 * @return {number}
 */
var maxRunTime = function(n, batteries) {
    let total = 0;
    for (const b of batteries) total += b;
    let lo = 1, hi = Math.floor(total / n);
    const feasible = (T) => {
        let s = 0;
        for (const b of batteries) {
            s += b < T ? b : T;
        }
        return s >= n * T;
    };
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);
        if (feasible(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
};
