```javascript
/**
 * @param {number} maxTime
 * @param {number[][]} edges
 * @param {number[]} passingFees
 * @return {number}
 */
var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const INF = Number.MAX_SAFE_INTEGER;
    // dp[v] = min cost to reach v within time t (best over all t' <= t)
    const dp = new Array(n).fill(INF);
    dp[0] = passingFees[0];
    // We need exact-time layers; keep history of layers.
    const layers = new Array(maxTime + 1);
    layers[0] = dp;
    let answer = INF;
    if (n === 1) return passingFees[0];
    for (let t = 1; t <= maxTime; t++) {
        const cur = new Array(n).fill(INF);
        for (let i = 0; i < edges.length; i++) {
            const x = edges[i][0], y = edges[i][1], w = edges[i][2];
            if (w > t) continue;
            const prev = layers[t - w];
            if (prev[x] !== INF) {
                const c = prev[x] + passingFees[y];
                if (c < cur[y]) cur[y] = c;
            }
            if (prev[y] !== INF) {
                const c = prev[y] + passingFees[x];
                if (c < cur[x]) cur[x] = c;
            }
        }
        layers[t] = cur;
        if (cur[n - 1] < answer) answer = cur[n - 1];
    }
    return answer === INF ? -1 : answer;
};
