Standard prefix-sum approach: for each split, track the best first-length subarray ending before the second-length subarray starts, and vice versa.

```javascript
/**
 * @param {number[]} nums
 * @param {number} firstLen
 * @param {number} secondLen
 * @return {number}
 */
var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const solve = (L, M) => {
        let best = 0;
        let maxL = 0;
        for (let i = L + M; i <= n; i++) {
            // L-length subarray ending at i - M
            maxL = Math.max(maxL, prefix[i - M] - prefix[i - M - L]);
            const sumM = prefix[i] - prefix[i - M];
            best = Math.max(best, maxL + sumM);
        }
        return best;
    };

    return Math.max(solve(firstLen, secondLen), solve(secondLen, firstLen));
};
