```javascript
/**
 * @param {number[]} nums
 * @return {number}
 */
var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    // Pascal's triangle
    const C = [];
    for (let i = 0; i <= n; i++) {
        C.push(new Array(i + 1).fill(0n));
        C[i][0] = 1n;
        C[i][i] = 1n;
        for (let j = 1; j < i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }
    const solve = (arr) => {
        if (arr.length <= 2) return 1n;
        const root = arr[0];
        const left = [];
        const right = [];
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }
        const total = left.length + right.length;
        let res = C[total][left.length];
        res = (res * solve(left)) % MOD;
        res = (res * solve(right)) % MOD;
        return res;
    };
    const ans = (solve(nums) - 1n + MOD) % MOD;
    return Number(ans);
};
