/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const full = 1 << n;
    // dp[mask] = [sessions, timeUsedInLastSession]
    const dpSess = new Array(full).fill(Infinity);
    const dpUsed = new Array(full).fill(Infinity);
    dpSess[0] = 1;
    dpUsed[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dpSess[mask] === Infinity) continue;
        const s = dpSess[mask], u = dpUsed[mask];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const nm = mask | (1 << i);
