/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const n = s1.length;
    if (n !== s2.length) return false;
    if (s1 === s2) return true;
    const memo = new Map();

    const solve = (i, j, len) => {
        const key = i * 1000 + j * 31 + len;
        if (memo.has(key)) return memo.get(key);
        let res = false;
        if (s1.substr(i, len) === s2.substr(j, len)) {
            res = true;
        } else {
            const cnt = new Array(26).fill(0);
            for (let k = 0; k < len; k++) {
                cnt[s1.charCodeAt(i + k) - 97]++;
                cnt[s2.charCodeAt(j + k) - 97]--;
            }
            let ok = true;
            for (let c = 0; c < 26; c++) {
                if (cnt[c] !== 0) { ok = false; break; }
            }
            if (ok) {
                for (let k = 1; k < len && !res; k++) {
                    if (solve(i, j, k) && solve(i + k, j + k, len - k)) res = true;
                    else if (solve(i, j + len - k, k) && solve(i + k, j, len - k)) res = true;
                }
            }
        }
        memo.set(key, res);
        return res;
    };

    return solve(0, 0, n);
};
