/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const parent = new Array(n * n * 4);
    for (let i = 0; i < parent.length; i++) parent[i] = i;
    let count = parent.length;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a, b) => {
        const ra = find(a), rb = find(b);
        if (ra !== rb) {
            parent[ra] = rb;
            count--;
        }
    };
    const idx = (r, c, k) => (r * n + c) * 4 + k;

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];
            if (ch === '/') {
                union(idx(r, c, 0), idx(r, c, 3));
                union(idx(r, c, 1), idx(r, c, 2));
            } else if (ch === '\\') {
                union(idx(r, c, 0), idx(r, c, 1));
                union(idx(r, c, 2), idx(r, c, 3));
            } else {
