var isSolvable = function(words, result) {
    const n = result.length;
    for (const w of words) {
        if (w.length > n) return false;
    }
    const rev = words.map(w => w.split('').reverse().join(''));
    const rres = result.split('').reverse().join('');
    const assign = new Map();
    const used = new Array(10).fill(false);
    const nonZero = new Set();
    for (const w of words) if (w.length > 1) nonZero.add(w[0]);
    if (result.length > 1) nonZero.add(result[0]);

    const solve = (col, idx, carry, sum) => {
        if (col === n) return carry === 0;
        if (idx < rev.length) {
            const w = rev[idx];
            if (col >= w.length) return solve(col, idx + 1, carry, sum);
            const c = w[col];
            if (assign.has(c)) {
                return solve(col, idx + 1, carry, sum + assign.get(c));
            }
            for (let d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d === 0 && nonZero.has(c)) continue;
                used[d] = true;
                assign.set(c, d);
                if (solve(col, idx + 1, carry, sum + d)) return true;
                assign.delete(c);
                used[d] = false;
            }
            return false;
        }
        // result column
        const total = sum + carry;
        const digit = total % 10;
        const newCarry = Math.floor(total / 10);
        const r = rres[col];
        if (assign.has(r)) {
            if (assign.get(r) !== digit) return false;
            return solve(col + 1, 0, newCarry, 0);
        }
        if (used[digit]) return false;
        if (digit === 0 && nonZero.has(r)) return false;
        used[digit] = true;
        assign.set(r, digit);
        const ok = solve(col + 1, 0, newCarry, 0);
        assign.delete(r);
        used[digit] = false;
        return ok;
    };

    return solve(0, 0, 0, 0);
};
