/**
 * @param {number} n
 * @param {number[]} leftChild
 * @param {number[]} rightChild
 * @return {boolean}
 */
var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const indeg = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (leftChild[i] !== -1) {
            indeg[leftChild[i]]++;
            if (indeg[leftChild[i]] > 1) return false;
        }
        if (rightChild[i] !== -1) {
            indeg[rightChild[i]]++;
            if (indeg[rightChild[i]] > 1) return false;
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const visited = new Array(n).fill(false);
    const stack = [root];
    visited[root] = true;
    let count = 0;
    while (stack.length) {
        const u = stack.pop();
        count++;
        for (const v of [leftChild[u], rightChild[u]]) {
            if (v !== -1) {
                if (visited[v]) return false;
                visited[v] = true;
                stack.push(v);
            }
        }
    }
    return count === n;
};
